import inspect
from click.testing import CliRunner

base = {'keep': 'value', 'remove': None, 'replace': 'old', 'restore': None}
overrides = {'replace': None, 'restore': 'new', 'empty': ''}
runner = CliRunner(env=base)
merged = dict(base, **overrides)
assert runner.make_env(overrides) == merged
assert runner.make_env(overrides, strip_none=False) == merged
assert runner.make_env(overrides, strip_none=True) == {'keep': 'value', 'restore': 'new', 'empty': ''}
assert runner.make_env(strip_none=True) == {'keep': 'value', 'replace': 'old'}
assert runner.make_env() == base
assert CliRunner().make_env(strip_none=True) == {}
assert base == {'keep': 'value', 'remove': None, 'replace': 'old', 'restore': None}
assert overrides == {'replace': None, 'restore': 'new', 'empty': ''}
assert inspect.signature(CliRunner.make_env).parameters['strip_none'].kind is inspect.Parameter.KEYWORD_ONLY
print('Focused checks passed')
